"""Assorted helpers."""

from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple


def chunk(items: Sequence[Any], size: int) -> List[List[Any]]:
    return [list(items[i:i + size]) for i in range(0, len(items), size)]


def flatten(nested: Iterable[Iterable[Any]]) -> List[Any]:
    return [item for group in nested for item in group]


def index_by(items: Iterable[Any], key: str) -> Dict[Any, Any]:
    return {getattr(item, key): item for item in items}


def first_where(items: Iterable[Any], predicate) -> Optional[Any]:
    for item in items:
        if predicate(item):
            return item
    return None


def partition(items: Iterable[Any], predicate) -> Tuple[List[Any], List[Any]]:
    yes: List[Any] = []
    no: List[Any] = []
    for item in items:
        (yes if predicate(item) else no).append(item)
    return yes, no


def coalesce(*values: Any) -> Optional[Any]:
    for value in values:
        if value is not None:
            return value
    return None


